validator:
function validate(input) {
  const [{ Friends = [], Activities = [] }] = input;
  const ids = new Set(), names = new Set(), used = new Set(), friends = new Set();
  for (const [id, name] of Activities) {
    if (id === null || name === null) return 'Activities rows may not contain null.';
    if (ids.has(id)) return `Activity id ${id} appears twice.`;
    if (names.has(name.toLowerCase())) return `Activity ${name} appears twice.`;
    ids.add(id); names.add(name.toLowerCase());
  }
  for (const [id, name, activity] of Friends) {
    if (id === null || name === null || activity === null) return 'Friends rows may not contain null.';
    if (friends.has(id)) return `Friend id ${id} appears twice.`;
    if (!names.has(activity.toLowerCase())) return `Friend ${id} does an unknown activity ${activity}.`;
    friends.add(id); used.add(activity.toLowerCase());
  }
  if (used.size !== names.size) return 'Every activity needs at least one participant.';
  return null;
}

generator:
function generate(rand, size) {
  const people = ['Jonathan D.', 'Jade W.', 'Victor J.', 'Elvis Q.', 'Daniel A.', 'Bob B.', 'Mia K.', 'Omar S.'];
  const pool = ['Eating', 'Singing', 'Horse Riding', 'Dancing', 'Reading', 'Hiking'];
  const small = size === 'small';
  const kinds = small ? Math.floor(rand() * 5) : 40;
  const names = small ? pool.slice(0, kinds) : Array.from({ length: kinds }, (_, i) => `Hobby ${i + 1}`);
  const Activities = names.map((name, i) => [i + 1, name]);
  // Every activity gets one participant; the rest go to random activities so counts collide and differ.
  const picks = [...names];
  const extra = kinds === 0 ? 0 : small ? Math.floor(rand() * (9 - kinds)) : 2000 - kinds;
  for (let i = 0; i < extra; i++) picks.push(names[Math.floor(Math.pow(rand(), small ? 1 : 2) * kinds)]);
  for (let i = picks.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [picks[i], picks[j]] = [picks[j], picks[i]]; }
  const Friends = picks.map((activity, i) => [i + 1, people[Math.floor(rand() * people.length)], activity]);
  return [{ Friends, Activities }];
}
